def transform(grid):
    g = np.array(grid)
    out = g.copy()
    H, W = g.shape
    comps = components(g == 0, diagonal=False)
    border, inner = [], []
    for c in comps:
        if any(y == 0 or x == 0 or y == H - 1 or x == W - 1 for y, x in c):
            border.append(c)
        else:
            inner.append(c)
    for c in border:
        for y, x in c:
            out[y, x] = 2
    emit(out, "Every 0-region (4-connected) that touches the grid border is coloured 2.")
    for c in inner:
        for y, x in c:
            out[y, x] = 5
    emit(out, "Every 0-region fully enclosed by the 1/3 walls is coloured 5.")
    return out
